insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$1609a45c-9b80-4840-892d-cea86cd202d5$t$, $t$19711$t$, $t$amoxicillin / clavulanate$t$, $t$Amoxicillin and clavulanate potassium for oral suspension, 600 mg/42.9 mg per 5 mL is indicated for the treatment of pediatric patients aged 3 months to 12 years weighing less than or equal to 40 kg with: Recurrent or persistent acute otitis media due to S. pneumoniae (penicillin MICs less than or equal to 2 mcg/mL), H. influenzae (including beta-lactamase-producing strains), or M. …$t$, $t$Pediatric Patients aged 3 months to 12 years weighing less than or equal to 40 kg: 90 mg/kg/day divided every 12 hours, administered for 10 days. 2.1 Important Administration Instructions To minimize the potential for gastrointestinal intolerance, amoxicillin and clavulanate potassium for oral suspension, 600 mg/42.9 mg per 5 mL should be taken at the start of a meal. …$t$, $t$Serious (including fatal) hypersensitivity reactions: Discontinue amoxicillin and clavulanate potassium for oral suspension, 600 mg/42.9 mg per 5 mL if a reaction occurs and institute appropriate therapy. Severe cutaneous adverse reactions (SCAR): Monitor closely. Discontinue if rash progresses. Drug-induced enterocolitis syndrome (DIES) has been reported with use of amoxicillin, a component of amoxicillin and clavulanate potassium for oral suspension, 600 mg/42.9 mg per 5 mL. …$t$, $t$In labeling: Anaphylactic reactions Severe Cutaneous Adverse Reactions (SCAR) Drug-Induced Enterocolitis Syndrome (DIES) Hepatic Dysfunction Clostridioides difficile- Associated Diarrhea (CDAD) Skin Rash in Patients with Mononucleosis The most frequently reported adverse reactions (incidence rate > 4 %) were coughing, vomiting, contact dermatitis (i.e., diaper rash), fever, upper respiratory tract infection, and diarrhea. …$t$, $t$Coadministration with probenecid is not recommended. Concomitant use of amoxicillin and clavulanate potassium for oral suspension, 600 mg/42.9 mg per 5 mL with oral anticoagulants may increase the prolongation of prothrombin time. Coadministration with allopurinol increases the risk of rash. Amoxicillin and clavulanate potassium for oral suspension, 600 mg/42.9 mg per 5 mL may reduce efficacy of oral contraceptives. 7.1 Probenecid Probenecid decreases the renal tubular secretion of amoxicillin. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=00b86913-50c8-443f-8467-f4f499d358af$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$ea9aaee9-4e02-4272-9a6f-ffeecd5d183c$t$, $t$282448$t$, $t$artemether / lumefantrine$t$, $t$Coartem Tablets are indicated for treatment of acute, uncomplicated malaria infections due to Plasmodium falciparum (P. falciparum) in patients 2 months of age and older with a bodyweight of 5 kg and above. Coartem Tablets have been shown to be effective in geographical regions where resistance to chloroquine has been reported . Limitations of Use : Coartem Tablets are not approved for patients with severe or complicated P. falciparum malaria. Coartem Tablets are not approved for the prevention of malaria. …$t$, $t$Coartem Tablets should be taken with food. Tablets may be crushed and mixed with 1 to 2 teaspoons of water immediately prior to administration to patients, including children. Coartem Tablets should be administered over 3 days for a total of 6 doses: an initial dose, second dose after 8 hours, and then twice-daily (morning and evening) for the following 2 days. The adult dosage for patients with bodyweight of 35 kg and above is 4 tablets per dose for a total of 6 doses. …$t$, $t$Avoid use in patients with known QT prolongation, those with hypokalemia or hypomagnesemia, and those taking other drugs that prolong the QT interval. Halofantrine and Coartem Tablets should not be administered within one month of each other due to potential additive effects on the QT interval. Antimalarials should not be given concomitantly, unless there is no other treatment option, due to limited safety data. …$t$, $t$The following serious and otherwise important adverse reactions are discussed in greater detail in other sections of labeling: Hypersensitivity Reactions Prolongation of the QT Interval Use of QT Prolonging Drugs and Other Antimalarials Drug Interactions with CYP3A4 Drug Interactions with CYP2D6 The most common adverse reactions in adults (greater than 30%) are headache, anorexia, dizziness, asthenia, arthralgia, and myalgia. …$t$, $t$Inducers: Potential for loss of antimalarial efficacy. CYP3A4 Inhibitors: Use cautiously due to potential for QT prolongation. Antiretrovirals: Use cautiously due to potential for QT prolongation, loss of antiviral efficacy, or loss of antimalarial efficacy of Coartem Tablets. Mefloquine: If used immediately before treatment, monitor for decreased efficacy of Coartem Tablets and encourage food consumption. Hormonal Contraceptives: Effectiveness may be reduced; use an additional method of birth control. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$b9b0434b-6226-480c-8fb9-525952beaddc$t$, $t$1191$t$, $t$aspirin$t$, $t$For the temporary relief of minor aches and pains or as recommended by your doctor. Because of its delayed action, this product will not provide fast relief of headaches or other symptoms needing immediate relief. ask your doctor about other uses for safety coated 81 mg aspirin$t$, $t$Drink a full glass of water with each dose adults and children 12 years and over: take 4 to 8 tablets every 4 hours not to exceed 48 tablets in 24 hours unless directed by a doctor children under 12 years: consult a doctor$t$, $t$Reye's syndrome : Children and teenagers who have or are recovering from chicken pox or flu-like symptoms should not use this product. When using this product, if changes in behavior with nausea and vomiting occur, consult a doctor because these symptoms could be an early sign of Reye's syndrome, a rare but serious illness. …$t$, $t$Stop use and ask a doctor if an allergic reaction occurs. Seek medical help right away. you experience any of the following signs of stomach bleeding: feel faint vomit blood have bloody or black stool have stomach pain that does not get better pain gets worse or lasts more than 10 days redness or swelling is present ringing in the ears or loss of hearing occurs new symptoms occur These could be signs of a serious condition$t$, $t$Ask a doctor or pharmacist before use if you are taking a prescription drug for gout diabetes arthritis$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0058175f-3474-40c3-a046-6cfaec86d84b$t$, now())
