insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$5179f55d-abef-4822-b8a0-4f1b34d30a60$t$, $t$1596$t$, $t$bisacodyl$t$, $t$For relief of occasional constipation and irregularity this product generally produces bowel movement in 6 to 12 hours$t$, $t$Take with a glass of water do not take more than directed adults and children 12 years and older: take 1 to 3 tablets in a single daily dose children 12 and under: ask a doctor$t$, $t$Do not use if you cannot swallow without chewing Ask a doctor before use if you have • stomach pain, nausea, vomiting • noticed a sudden change in bowel habits that lasts more than 2 weeks When using this product • do not chew or crush tablet(s) • do not use within 1 hour after taking an antacid or milk • it may cause stomach discomfort, faintness and cramps Stop use and ask a doctor if • you have rectal bleeding or no bowel movement after using this product. These could be signs of a serious condition. …$t$, null, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=017bc27d-a951-48a4-8f65-90fcbe6dbea0$t$, now())
