insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$22ac52d9-9282-47b1-8d48-0b837760abb4$t$, $t$1897$t$, $t$calcium carbonate$t$, $t$Relieves acid indigestion heartburn sour stomach upset stomach associated with these symptoms$t$, $t$Take one to four tablets daily. do not take more than 4 tablets in 24 hours do not use the maximum dosage for more than 2 weeks$t$, $t$Ask a doctor or pharmacist before use if you are taking a prescription drug. Antacids may interact with certain prescription drugs. Stop use and ask a doctor if symptoms last more than 2 weeks. If pregnant or breast-feeding, ask a health professional before use.$t$, null, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0108b97f-02e9-4f86-9f33-cde4f919affd$t$, now())
