insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$aafd5e87-aa7d-4b21-b385-8f74ef1addc5$t$, $t$2193$t$, $t$ceftriaxone$t$, $t$To reduce the development of drug-resistant bacteria and maintain the effectiveness of Ceftriaxone for Injection and other antibacterial drugs, Ceftriaxone for Injection should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. …$t$, $t$Ceftriaxone for Injection USP, Pharmacy Bulk Package bag SmartPak ® should be used only in patients who require a 1 gram dose and not any fraction thereof. Ceftriaxone for Injection USP, Pharmacy Bulk Package bag SmartPak ® should not be used in patients who require less than the 1 gram dose of Ceftriaxone. THIS PHARMACY BULK PACKAGE REQUIRES RECONSTITUTION WITH STERILE WATER FOR INJECTION, USP TO A CONCENTRATION OF 100 mg per mL AND FURTHER DILUTION IN 50 mL OF A COMPATIBLE SOLUTION. …$t$, $t$Hypersensitivity reactions: Include anaphylaxis and serious skin reactions. Cross hypersensitivity may occur in up to 10% of patients with a history of penicillin allergy. If an allergic reaction occurs, discontinue the drug . Interaction with Calcium-containing products: Precipitation can occur. Do not administer simultaneously with calcium-containing I.V. solutions . Neurological adverse reactions: Serioous neurological adverse reactions have been reported during postmarketing surveillance. …$t$, $t$The following serious adverse reactions to ceftriaxone are described below and elsewhere in the labeling: Hypersensitivity reactions Ceftriaxone-calcium precipitates Clostridium difficile -associated diarrhea Hemolytic anemia The most common adverse reactions occurring in >2% of patients receiving ceftriaxone include diarrhea, eosinophilia, thrombocytosis, leukopenia, and elevations of SGOT and SGPT. …$t$, $t$Vancomycin, amsacrine, aminoglycosides and fluconazole are physically incompatible. Calcium-containing products: precipitation can occur. 7.1 Vancomycin, Amsacrine, Aminoglycosides, and Fluconazole Vancomycin, amsacrine, aminoglycosides, and fluconazole are physically incompatible with ceftriaxone in admixtures . 7.2 Calcium-containing Products Precipitation of ceftriaxone-calcium can occur when Ceftriaxone for Injection is mixed with calcium-containing solutions in the same intravenous administration line. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=5cd2d96f-83e5-4326-ae87-d0ede4ba493a$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$c763bb55-63a0-4958-a66d-629aade798eb$t$, $t$20610$t$, $t$cetirizine$t$, $t$Temporarily relieves these symptoms due to hay fever or other upper respiratory allergies: runny nose sneezing itchy, watery eyes itching of the nose or throat$t$, $t$May be taken with or without water chew or crush tablets completely before swallowing children 2 to under 6 years of age Chew and swallow 1 tablet (2.5 mg) once daily; If needed, dose can be increased to a maximum of 2 tablets (5 mg) once daily or 1 tablet (2.5 mg) every 12 hours. Do not give more than 2 tablets (5 mg) in 24 hours. adults and children 6 years and over Chew and swallow 2 tablets (5 mg) or 4 tablets (10 mg) once daily depending upon severity of symptoms; …$t$, $t$Do not use if you have ever had an allergic reaction to this product or any of its ingredients or to an antihistamine containing hydroxyzine. Ask a doctor before use if you have liver or kidney disease. Your doctor should determine if you need a different dose. Ask a doctor or pharmacist before use if you are taking tranquilizers or sedatives. …$t$, $t$Stop use and ask a doctor if an allergic reaction to this product occurs. Seek medical help right away.$t$, $t$Ask a doctor or pharmacist before use if you are taking tranquilizers or sedatives.$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=013ce40e-37c9-4b84-b530-ed895f60ce0e$t$, now())
