insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$b07aa054-52ee-4d37-9ee8-e741adfe3af2$t$, $t$2400$t$, $t$chlorpheniramine$t$, $t$Temporarily relieves these symptoms due to hay fever or other upper respiratory allergies: sneezing runny nose itchy, watery eyes itching of the nose or throat$t$, $t$Take every 4 to 6 hours, or as directed by a doctor adults and children 12 years and over 1 tablet. Do not exceed 6 tablets in 24 hours. children 6 to under 12 years 1/2 tablet (break tablet in half). Do not exceed 3 whole tablets in 24 hours. children under 6 years do not use$t$, $t$Do not use to make a child sleepy. Ask a doctor before use if you have glaucoma a breathing problem such as emphysema or chronic bronchitis difficulty in urination due to enlargement of the prostate gland Ask a doctor or pharmacist before use if you are taking sedatives or tranquilizers. …$t$, null, $t$Ask a doctor or pharmacist before use if you are taking sedatives or tranquilizers.$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=04ca3806-72be-47d4-9fea-5b0dee087683$t$, now())
