insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$5c44c958-0671-49c2-ba9a-ea0f11d3a5fd$t$, $t$2551$t$, $t$ciprofloxacin$t$, $t$Ciprofloxacin is a fluoroquinolone antibacterial indicated in adults (18 years of age and older) with the following infections caused by designated, susceptible bacteria and in pediatric patients where indicated: Skin and Skin Structure Infections Bone and Joint Infections Complicated Intra-Abdominal Infections Infectious Diarrhea Typhoid Fever (Enteric Fever) Uncomplicated Cervical and Urethral Gonorrhea Inhalational Anthrax post-exposure in adult and pediatric patients Plague in adult and pediatric patients …$t$, $t$Ciprofloxacin tablets should be administered orally as described in the appropriate Dosage Guidelines tables. Adult Dosage Guidelines Infection Dose Frequency Duration Skin and Skin Structure 500-750mg every 12 hours 7 to 14 days Bone and Joint 500-750mg every 12 hours 4 to 8 weeks Complicated Intra-Abdominal 500mg every 12 hours 7 to 14 days Infectious Diarrhea 500mg every 12 hours 5 to 7 days Typhoid Fever 500mg every 12 hours 10 days Uncomplicated Gonorrhea 250mg single dose single dose Inhalational anthrax …$t$, $t$WARNING: SERIOUS ADVERSE REACTIONS INCLUDING TENDINITIS, TENDON RUPTURE, PERIPHERAL NEUROPATHY, CENTRAL NERVOUS SYSTEM EFFECTS AND EXACERBATION OF MYASTHENIA GRAVIS Fluoroquinolones, including ciprofloxacin, have been associated with disabling and potentially irreversible serious adverse reactions that have occurred together including: Tendinitis and tendon rupture Peripheral neuropathy Central nervous system effects Discontinue ciprofloxacin immediately and avoid the use of fluoroquinolones, including …$t$, $t$The following serious and otherwise important adverse drug reactions are discussed in greater detail in other sections of labeling: Disabling and Potentially Irreversible Serious Adverse Reactions Tendinitis and Tendon Rupture Peripheral Neuropathy Central Nervous System Effects Exacerbation of Myasthenia Gravis Other Serious and Sometimes Fatal Adverse Reactions Hypersensitivity Reactions Hepatotoxicity Risk of Aortic Aneurysm and Dissection Serious Adverse Reactions with Concomitant Theophylline Clostridioides …$t$, $t$Ciprofloxacin is an inhibitor of human cytochrome P450 1A2 (CYP1A2) mediated metabolism. Co-administration of ciprofloxacin with other drugs primarily metabolized by CYP1A2 results in increased plasma concentrations of these drugs and could lead to clinically significant adverse events of the co-administered drug. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0c355077-7361-41d0-9e82-eb31beaf5daa$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$6870e6d0-b65c-4960-8db4-bf5cf92ce770$t$, $t$2623$t$, $t$clotrimazole$t$, $t$Prescription Clotrimazole Topical Solution product is indicated for the topical treatment of candidiasis due to Candida albicans and tinea versicolor due to Malassezia furfur . This formulation is also available as a nonprescription product which is indicated for the topical treatment of the following dermal infections: tinea pedis, tinea cruris, and tinea corporis due to Trichophyton rubrum , Trichophyton mentagrophytes, Epidermophyton fluoccosum, and Microsporum canis .$t$, $t$Gently massage sufficient Clotrimazole Topical Solution, USP 1% into the affected and surrounding skin areas twice a day, in the morning and evening. Clinical improvement, with relief of pruritus, usually occurs within the first week of treatment with Clotrimazole Topical Solution, USP 1%. If the patient shows no clinical improvement after 4 weeks of treatment with Clotrimazole Topical Solution, USP 1% the diagnosis should be reviewed.$t$, $t$Clotrimazole Topical Solution is not for ophthalmic use.$t$, $t$The following adverse reactions have been reported in connection with the use of clotrimazole: erythema, stinging, blistering, peeling, edema, pruritius, urticaria, burning, and general irritation of the skin.$t$, $t$Drug Interactions Synergism or antagonism between clotrimazole and nystatin, or amphotericin B, or flucytosine against strains of C. albicans has not been reported.$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=02df90b9-4879-4e73-b03a-0e96f3d099ea$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$86b65727-c48d-4b24-9c09-024af49b8495$t$, $t$1008359$t$, $t$levonorgestrel / ethinyl estradiol$t$, $t$Levonorgestrel and ethinyl estradiol tablets are indicated for the prevention of pregnancy in women who elect to use oral contraceptives as a method of contraception. Oral contraceptives are highly effective for pregnancy prevention. Table 2 lists the typical unintended pregnancy rates for users of combination oral contraceptives and other methods of contraception. The efficacy of these contraceptive methods, except sterilization, the IUD, and implants, depend upon the reliability with which they are used. …$t$, $t$To achieve maximum contraceptive effectiveness, levonorgestrel and ethinyl estradiol tablets must be taken exactly as directed and at intervals not exceeding 24 hours. The possibility of ovulation and conception prior to initiation of medication should be considered. Women who do not wish to become pregnant after discontinuation should be advised to immediately use another method of birth control. …$t$, $t$Cigarette smoking increases the risk of serious adverse effects on the heart and blood vessels from oral contraceptive use. This risk increases with age and with the amount of smoking (15 or more cigarettes per day has been associated with a significantly increased risk) and is quite marked in women over 35 years of age. Women who use oral contraceptives should not smoke.$t$, $t$An increased risk of the following serious adverse reactions (see WARNINGS section for additional information) has been associated with the use of oral contraceptives: Thromboembolic and thrombotic disorders and other vascular problems (including thrombophlebitis and venous thrombosis with or without pulmonary embolism, mesenteric thrombosis, arterial thromboembolism, myocardial infarction, cerebral hemorrhage, cerebral thrombosis, transient ischemic attack), carcinoma of the reproductive organs and breasts, …$t$, $t$9. Drug Interactions Changes in Contraceptive Effectiveness Associated with Coadministration of Other Products: Contraceptive effectiveness may be reduced when hormonal contraceptives are coadministered with antibiotics, anticonvulsants, and other drugs that increase the metabolism of contraceptive steroids. This could result in unintended pregnancy or unscheduled bleeding. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=44fbc5ae-5682-471f-a12a-955e8b4d233a$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$5e7d658e-d221-4877-a85b-b632fbbf9fb3$t$, $t$10831$t$, $t$sulfamethoxazole / trimethoprim$t$, $t$To reduce the development of drug-resistant bacteria and maintain the effectiveness of sulfamethoxazole and trimethoprim tablets, USP and other antibacterial drugs, sulfamethoxazole and trimethoprim tablets, USP should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. …$t$, $t$Sulfamethoxazole and trimethoprim tablets are contraindicated in pediatric patients less than 2 months of age. Urinary Tract Infections and Shigellosis in Adults and Pediatric Patients, and Acute Otitis Media in Children Adults The usual adult dosage in the treatment of urinary tract infections is 1 sulfamethoxazole and trimethoprim DS (double strength) tablet or 2 sulfamethoxazole and trimethoprim tablets every 12 hours for 10 to 14 days. …$t$, $t$Embryofetal Toxicity Some epidemiologic studies suggest that exposure to sulfamethoxazole and trimethoprim during pregnancy may be associated with an increased risk of congenital malformations, particularly neural tube defects, cardiovascular malformations, urinary tract defects, oral clefts, and club foot. If sulfamethoxazole and trimethoprim is used during pregnancy, or if the patient becomes pregnant while taking this drug, the patient should be advised of the potential hazards to the fetus. …$t$, $t$The most common adverse effects are gastrointestinal disturbances (nausea, vomiting, anorexia) and allergic skin reactions (such as rash and urticaria). FATALITIES ASSOCIATED WITH THE ADMINISTRATION OF SULFONAMIDES, ALTHOUGH RARE, HAVE OCCURRED DUE TO SEVERE REACTIONS, INCLUDING STEVENS-JOHNSON SYNDROME, TOXIC EPIDERMAL NECROLYSIS, FULMINANT HEPATIC NECROSIS, AGRANULOCYTOSIS, APLASTIC ANEMIA AND OTHER BLOOD DYSCRASIAS (SEE WARNINGS SECTION). …$t$, $t$Drug Interactions Potential for Sulfamethoxazole and Trimethoprim to Affect Other Drugs Trimethoprim is an inhibitor of CYP2C8 as well as OCT2 transporter. Sulfamethoxazole is an inhibitor of CYP2C9. Caution is recommended when sulfamethoxazole and trimethoprim is co-administered with drugs that are substrates of CYP2C8 and 2C9 or OCT2. In elderly patients concurrently receiving certain diuretics, primarily thiazides, an increased incidence of thrombocytopenia with purpura has been reported. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=079c828c-148f-45b9-966e-d8906043b2a2$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$90ab5fb0-884e-4933-a773-3f3d2651b1e5$t$, $t$10831$t$, $t$sulfamethoxazole / trimethoprim$t$, $t$To reduce the development of drug-resistant bacteria and maintain the effectiveness of sulfamethoxazole and trimethoprim tablets, USP and other antibacterial drugs, sulfamethoxazole and trimethoprim tablets, USP should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. …$t$, $t$Sulfamethoxazole and trimethoprim tablets are contraindicated in pediatric patients less than 2 months of age. Urinary Tract Infections and Shigellosis in Adults and Pediatric Patients, and Acute Otitis Media in Children Adults The usual adult dosage in the treatment of urinary tract infections is 1 sulfamethoxazole and trimethoprim DS (double strength) tablet or 2 sulfamethoxazole and trimethoprim tablets every 12 hours for 10 to 14 days. …$t$, $t$Embryofetal Toxicity Some epidemiologic studies suggest that exposure to sulfamethoxazole and trimethoprim during pregnancy may be associated with an increased risk of congenital malformations, particularly neural tube defects, cardiovascular malformations, urinary tract defects, oral clefts, and club foot. If sulfamethoxazole and trimethoprim is used during pregnancy, or if the patient becomes pregnant while taking this drug, the patient should be advised of the potential hazards to the fetus. …$t$, $t$The most common adverse effects are gastrointestinal disturbances (nausea, vomiting, anorexia) and allergic skin reactions (such as rash and urticaria). FATALITIES ASSOCIATED WITH THE ADMINISTRATION OF SULFONAMIDES, ALTHOUGH RARE, HAVE OCCURRED DUE TO SEVERE REACTIONS, INCLUDING STEVENS-JOHNSON SYNDROME, TOXIC EPIDERMAL NECROLYSIS, FULMINANT HEPATIC NECROSIS, AGRANULOCYTOSIS, APLASTIC ANEMIA AND OTHER BLOOD DYSCRASIAS (SEE WARNINGS SECTION). …$t$, $t$Drug Interactions Potential for Sulfamethoxazole and Trimethoprim to Affect Other Drugs Trimethoprim is an inhibitor of CYP2C8 as well as OCT2 transporter. Sulfamethoxazole is an inhibitor of CYP2C9. Caution is recommended when sulfamethoxazole and trimethoprim is co-administered with drugs that are substrates of CYP2C8 and 2C9 or OCT2. In elderly patients concurrently receiving certain diuretics, primarily thiazides, an increased incidence of thrombocytopenia with purpura has been reported. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=079c828c-148f-45b9-966e-d8906043b2a2$t$, now())
