insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$1ff758bc-7816-47e5-b91d-1a8cd1f27c12$t$, $t$3289$t$, $t$dextromethorphan$t$, $t$Temporarily relieves these common cold/flu symptoms minor aches and pains headache sore throat fever runny nose and sneezing cough due to minor throat and bronchial irritation$t$, $t$Do not take more than directed (see Overdose warning) do not take more than 4 doses in any 24-hour period measure only with dosing cup provided. Do not use any other dosing device. mL = milliliter keep dosing cup with product adults and children 12 years and over: 30 mL every 6 hours children under 12 years of age: do not use when using other Daytime or Nighttime products, carefully read each label to ensure correct dosing$t$, $t$Liver warning: This product contains acetaminophen. Severe liver damage may occur if you take: more than 4000 mg of acetaminophen in 24 hours with other drugs containing acetaminophen 3 or more alcoholic drinks everyday while using this product Allergy alert: Acetaminophen may cause severe skin reactions. Symptoms may include: skin reddening blisters rash if a skin reaction occurs, stop use and seek medical help right away. …$t$, $t$Stop use and ask a doctor if pain or cough gets worse or last more than 7 days fever gets worse or lasts more than 3 days redness or swelling is present new symptoms occur cough comes back or occurs with rash or headache that lasts. These could be a signs of a serious conditions.$t$, $t$Ask a doctor or pharmacist before use if you are taking sedatives or tranquilizers the blood thinning drug warfarin$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=025f6622-a6db-4a5c-aebd-5d54172fa4a1$t$, now())
