insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$ef918219-bbc8-4822-aea0-c2522d37dad6$t$, $t$4850$t$, $t$dextrose$t$, $t$Dextrose Injection is indicated as source of calories and fluid replenishment when mixed with amino acids or other compatible intravenous fluids for patients requiring parenteral nutrition (PN) when oral or enteral nutrition is not possible, insufficient or contraindicated. …$t$, $t$2 DOSAGE AND ADMINISTRATION • Pharmacy Bulk Package. Not for direct intravenous infusion. • For slow intravenous infusion only into a: o Central vein, if final dextrose concentration is greater than 5% or osmolality is greater than 900 mOsm/L approximately. o Peripheral vein, if final dextrose concentration 5% or less and osmolality is less than 900 mOsm/L approximately. …$t$, $t$5 WARNINGS AND PRECAUTIONS • Pulmonary Embolism due to Pulmonary Vascular Precipitates : If signs of pulmonary distress occur, stop the infusion and initiate a medical evaluation. • Hyperglycemia or Hyperosmolar Hyperglycemic State : Monitor blood glucose and administer insulin as needed. • Hypersensitivity Reactions : Monitor for signs and symptoms and discontinue infusion if reactions occur. …$t$, $t$The following adverse reactions associated with the use of Dextrose Injection were identified in clinical trials or postmarketing reports. Because these reactions were reported voluntarily from a population of uncertain size, it is not always possible to estimate their frequency, reliably, or to establish a causal relationship to drug exposure. …$t$, $t$Other Products that Affect Glycemic Control, Vasopressin or Fluid and/or Electrolyte Balance : Monitor blood glucose concentrations, fluid balance serum electrolyte concentrations and acid-base balance. 7.1 Other Products that Affect Glycemic Control or Fluid and/or Electrolyte Balance Dextrose Injection can affect glycemic control and fluid and/or electrolyte balance . …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0332f34a-7038-47cc-ba59-d55cad6b73ca$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$d20057a1-3877-4d7d-881e-cd3cd5461b0e$t$, $t$3322$t$, $t$diazepam$t$, $t$Diazepam is indicated for the management of anxiety disorders or for the short-term relief of the symptoms of anxiety. Anxiety or tension associated with the stress of everyday life usually does not require treatment with an anxiolytic. In acute alcohol withdrawal, diazepam may be useful in the symptomatic relief of acute agitation, tremor, impending or acute delirium tremens and hallucinosis. …$t$, $t$Dosage should be individualized for maximum beneficial effect. The usual recommended dose in older children and adults ranges from 2 mg to 20 mg intramuscular or intravenous, depending on the indication and its severity. In some conditions, e.g., tetanus, larger doses may be required. (See dosage for specific indications.) In acute conditions the injection may be repeated within one hour although an interval of 3 to 4 hours is usually satisfactory. …$t$, $t$BOXED WARNING WARNING: RISKS FROM CONCOMITANT USE WITH OPIOIDS; ABUSE, MISUSE, AND ADDICTION; and DEPENDENCE AND WITHDRAWAL REACTIONS • Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death (see WARNINGS). • Reserve concomitant prescribing of these drugs in patients for whom alternative treatment options are inadequate. • Limit dosages and durations to the minimum required. …$t$, $t$Side effects most commonly reported were drowsiness, fatigue, and ataxia; venous thrombosis and phlebitis at the site of injection. Other adverse reactions less frequently reported include: CNS : Confusion, depression [including respiratory depressing (see WARNINGS; Pediatric Use )], dysarthria, headache, hypoactivity, slurred speech, syncope, tremor, vertigo. G.I. : Constipation, nausea. G.U. : Incontinence, changes in libido, urinary retention. Cardiovascular : Bradycardia, cardiovascular collapse, hypotension. …$t$, $t$The concomitant use of benzodiazepines and opioids increases the risk of respiratory depression because of actions at different receptor sites in the CNS that control respiration. Benzodiazepines interact at GABAA sites and opioids interact primarily at mµ receptors. When benzodiazepines and opioids are combined, the potential for benzodiazepines to significantly worsen opioid-related respiratory depression exists. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=1632f040-3b2c-43da-a42f-f2baf5ec778a$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$13cdee27-b88d-407a-a89f-46fbd65d62c5$t$, $t$3322$t$, $t$diazepam$t$, $t$Diazepam tablets are indicated for the management of anxiety disorders or for the short-term relief of the symptoms of anxiety. Anxiety or tension associated with the stress of everyday life usually does not require treatment with an anxiolytic. In acute alcohol withdrawal, diazepam tablets may be useful in the symptomatic relief of acute agitation, tremor, impending or acute delirium tremens and hallucinosis. …$t$, $t$Dosage should be individualized for maximum beneficial effect. While the usual daily dosages given below will meet the needs of most patients, there will be some who may require higher doses. In such cases dosage should be increased cautiously to avoid adverse effects. ADULTS: USUAL DAILY DOSE: Management of Anxiety Disorders and Relief of Symptoms of Anxiety. Depending upon severity of symptoms—2 mg to 10 mg, 2 to 4 times daily Symptomatic Relief in Acute Alcohol Withdrawal. …$t$, $t$WARNING: RISKS FROM CONCOMITANT USE WITH OPIOIDS; ABUSE, MISUSE, AND ADDICTION; and DEPENDENCE AND WITHDRAWAL REACTIONS • Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing of these drugs in patients for whom alternative treatment options are inadequate. Limit dosages and durations to the minimum required. …$t$, $t$Side effects most commonly reported were drowsiness, fatigue, muscle weakness, and ataxia. The following have also been reported: Central Nervous System: confusion, depression, dysarthria, headache, slurred speech, tremor, vertigo Gastrointestinal System: constipation, nausea, gastrointestinal disturbances Special Senses: blurred vision, diplopia, dizziness Cardiovascular System: hypotension Psychiatric and Paradoxical Reactions: stimulation, restlessness, acute hyperexcited states, anxiety, agitation, …$t$, $t$Drug Interactions Opioids The concomitant use of benzodiazepines and opioids increases the risk of respiratory depression because of actions at different receptor sites in the CNS that control respiration. Benzodiazepines interact at GABA A sites and opioids interact primarily at mu receptors. When benzodiazepines and opioids are combined, the potential for benzodiazepines to significantly worsen opioid-related respiratory depression exists. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=01f04ee4-fff9-499a-8213-984e16368084$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$ac4983ab-9406-4ade-b61c-afdf197ee171$t$, $t$3355$t$, $t$diclofenac$t$, $t$Diclofenac sodium topical solution is indicated for the treatment of the pain of osteoarthritis of the knee(s). Diclofenac sodium topical solution is a nonsteroidal anti-inflammatory drug indicated for the treatment of the pain of osteoarthritis of the knee(s).$t$, $t$The lowest effective dosage for the shortest duration consistent with individual patient treatment goals. The recommended dose is 2 pump actuations on each painful knee, 2 times a day. Apply diclofenac sodium topical solution, to clean, dry skin. Dispense 40 mg (2 pump actuations) directly onto the knee or first into the hand and then onto the knee. Spread evenly around front, back and sides of the knee. Wash hands completely after administering the product. …$t$, $t$WARNING: RISK OF SERIOUS CARDIOVASCULAR AND GASTROINTESTINAL EVENTS Cardiovascular Thrombotic Events Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction, and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use. . Diclofenac sodium topical solution is contraindicated in the setting of coronary artery bypass graft (CABG) surgery . …$t$, $t$Cardiovascular Thrombotic Events GI Bleeding, Ulceration and Perforation Hepatotoxicity Hypertension Heart Failure and Edema Renal Toxicity and Hyperkalemia Anaphylactic Reactions Serious Skin Reactions Hematologic Toxicity The most common adverse reactions with diclofenac sodium topical solution are application site reactions. . …$t$, $t$See Table 3 for clinically significant drug interactions with diclofenac. Table 3: Clinically Significant Drug Interactions with Diclofenac Drugs That Interfere with Hemostasis Clinical Impact: Diclofenac and anticoagulants such as warfarin have a synergistic effect on bleeding. The concomitant use of diclofenac and anticoagulants have increased the risk of serious bleeding compared to the use of either drug alone. Serotonin release by platelets plays an important role in hemostasis. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=02e90e33-384f-4e29-b508-2503def22214$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$c9992621-75e0-4bc4-9b5e-0f107bae0724$t$, $t$3355$t$, $t$diclofenac$t$, $t$Carefully consider the potential benefits and risks of diclofenac sodium delayed-release tablets and other treatment options before deciding to use diclofenac. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals ( see WARNINGS; Gastrointestinal Bleeding, Ulceration, and Perforation ). …$t$, $t$Carefully consider the potential benefits and risks of diclofenac sodium delayed-release tablets and other treatment options before deciding to use diclofenac. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals (see WARNINGS; Gastrointestinal Bleeding, Ulceration, and Perforation ) . After observing the response to initial therapy with diclofenac, the dose and frequency should be adjusted to suit an individual patient's needs. …$t$, $t$WARNING: RISK OF SERIOUS CARDIOVASCULAR AND GASTROINTESTINAL EVENTS Cardiovascular Thrombotic Events Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use (see WARNINGS ). …$t$, $t$Cardiovascular Thrombotic Events (see WARNINGS ) GI Bleeding, Ulceration and Perforation (see WARNINGS ) Hepatotoxicity (see WARNINGS ) Hypertension (see WARNINGS ) Heart Failure and Edema (see WARNINGS ) Renal Toxicity and Hyperkalemia (see WARNINGS ) Anaphylactic Reactions (see WARNINGS ) Serious Skin Reactions (see WARNINGS ) Hematologic Toxicity (see WARNINGS ) Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical …$t$, $t$Drug Interactions See Table 2 for clinically significant drug interactions with diclofenac. Table 2: Clinically Significant Drug Interactions with Diclofenac Drugs That Interfere with Hemostasis Clinical Impact: Diclofenac and anticoagulants such as warfarin have a synergistic effect on bleeding. The concomitant use of diclofenac and anticoagulants have an increased risk of serious bleeding compared to the use of either drug alone. Serotonin release by platelets plays an important role in hemostasis. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0cefb675-c54e-44eb-b35c-38354b77eddd$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$d31975c0-1700-4036-91a4-e6457d2ade85$t$, $t$3640$t$, $t$doxycycline$t$, $t$To reduce the development of drug-resistant bacteria and maintain effectiveness of doxycycline and other antibacterial drugs, doxycycline should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. …$t$, $t$The usual dosage and frequency of administration of doxycycline differs from that of the other tetracyclines. Exceeding the recommended dosage may result in an increased incidence of side effects. Adults: The usual dose of oral doxycycline is 200 mg on the first day of treatment (administered 100 mg every 12 hours) followed by a maintenance dose of 100 mg/day. In the management of more severe infections (particularly chronic infections of the urinary tract), 100 mg every 12 hours is recommended. …$t$, $t$The use of drugs of the tetracycline class during tooth development (last half of pregnancy, infancy and childhood to the age of 8 years) may cause permanent discoloration of the teeth (yellow-gray-brown). This adverse reaction is more common during long-term use of the drugs, but it has been observed following repeated short-term courses. Enamel hypoplasia has also been reported. …$t$, $t$Due to oral doxycycline's virtually complete absorption, side effects of the lower bowel, particularly diarrhea, have been infrequent. The following adverse reactions have been observed in patients receiving tetracyclines: Gastrointestinal: anorexia, nausea, vomiting, diarrhea, glossitis, dysphagia, enterocolitis, inflammatory lesions (with monilial overgrowth) in the anogenital region, and pancreatitis. Hepatotoxicity has been reported rarely. …$t$, $t$Drug Interactions Because tetracyclines have been shown to depress plasma prothrombin activity, patients who are on anticoagulant therapy may require downward adjustment of their anticoagulant dosage. Since bacteriostatic drugs may interfere with the bactericidal action of penicillin, it is advisable to avoid giving tetracyclines in conjunction with penicillin. Absorption of tetracyclines is impaired by antacids containing aluminum, calcium, or magnesium, and iron-containing preparations. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=00b2aa98-dea2-90c3-e063-6294a90a35d6$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$c2ffd2f5-fbe6-4a34-b0f7-4773cb57e2ca$t$, $t$6373$t$, $t$levonorgestrel$t$, $t$For women to reduce chance of pregnancy after unprotected sex (if a contraceptive failed or if you did not use birth control)$t$, $t$• take as soon as possible within 72 hours (3 days) after unprotected sex. The sooner you take it the better it will work. • if you vomit within 2 hours after taking the medication, call a healthcare professional to find out if you should repeat the dose$t$, $t$Allergy alert: Do not use if you have ever had an allergic reaction to levonorgestrel Sexually transmitted diseases (STDs) alert: This product does not protect against HIV/AIDS or other STDs Do not use • if you are already pregnant (because it will not work) • for regular birth control Ask a doctor or pharmacist before use if you are taking efavirenz (HIV medication) or rifampin (tuberculosis treatment) or medication for seizures (epilepsy). These medications may reduce the effectiveness of levonorgestrel. …$t$, null, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=01c8c95c-6fbe-4068-915d-74418a6bb570$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$ecf3748d-9f44-4a2b-bb72-18b7478f6792$t$, $t$3827$t$, $t$enalapril$t$, $t$Hypertension Enalapril maleate is indicated for the treatment of hypertension. Enalapril maleate is effective alone or in combination with other antihypertensive agents, especially thiazide-type diuretics. The blood pressure lowering effects of enalapril maleate and thiazides are approximately additive. Heart Failure Enalapril maleate is indicated for the treatment of symptomatic congestive heart failure, usually in combination with diuretics and digitalis. …$t$, $t$Hypertension In patients who are currently being treated with a diuretic, symptomatic hypotension occasionally may occur following the initial dose of enalapril maleate. The diuretic should, if possible, be discontinued for two to three days before beginning therapy with enalapril maleate to reduce the likelihood of hypotension (see WARNINGS, Hypotension ). If the patient's blood pressure is not controlled with enalapril maleate alone, diuretic therapy may be resumed. …$t$, $t$WARNING: FETAL TOXICITY See full prescribing information for complete boxed warning. When pregnancy is detected, discontinue enalapril maleate as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. (See WARNINGS: Fetal Toxicity .)$t$, $t$Enalapril maleate has been evaluated for safety in more than 10,000 patients, including over 1000 patients treated for one year or more. Enalapril maleate has been found to be generally well tolerated in controlled clinical trials involving 2987 patients. For the most part, adverse experiences were mild and transient in nature. …$t$, $t$Drug Interactions Neprilysin Inhibitors Patients taking concomitant neprilysin inhibitors may be at increased risk for angioedema (see WARNINGS ). Dual Blockade of the Renin-Angiotensin System (RAS) Dual blockade of the RAS with angiotensin receptor blockers, ACE inhibitors, or aliskiren is associated with increased risks of hypotension, hyperkalemia, and changes in renal function (including acute renal failure) compared to monotherapy. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=074fe718-88d8-365c-e063-6394a90a299d$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$e9369982-fc08-41d0-8192-97fd20fb27cd$t$, $t$4053$t$, $t$erythromycin$t$, $t$To reduce the development of drug-resistant bacteria and maintain the effectiveness of erythromycin tablets, USP and other antibacterial drugs, erythromycin tablets, USP should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. …$t$, $t$In most patients, erythromycin tablets are well absorbed and may be dosed orally without regard to meals. However, optimal blood levels are obtained when erythromycin tablets are given in the fasting state (at least 1/2 hour and preferably 2 hours before meals). Adults The usual dosage of Erythromycin Tablets is one 250 mg tablet four times daily in equally spaced doses or one 500 mg tablet every 12 hours. Dosage may be increased up to 4 g per day according to the severity of the infection. …$t$, $t$Hepatotoxicity There have been reports of hepatic dysfunction, including increased liver enzymes and hepatocellular and/or cholestatic hepatitis, with or without jaundice, occurring in patients receiving oral erythromycin products. QT Prolongation Erythromycin has been associated with prolongation of the QT interval and infrequent cases of arrhythmia. Cases of torsades de pointes have been spontaneously reported during postmarketing surveillance in patients receiving erythromycin. Fatalities have been reported. …$t$, $t$The most frequent side effects of oral erythromycin preparations are gastrointestinal and are dose-related. They include nausea, vomiting, abdominal pain, diarrhea and anorexia. Symptoms of hepatitis, hepatic dysfunction and/or abnormal liver function test results may occur (See WARNINGS ). Onset of pseudomembranous colitis symptoms may occur during or after antibacterial treatment (See WARNINGS ). …$t$, $t$Drug Interactions Serious adverse reactions have been reported in patients taking erythromycin concomitantly with CYP3A4 substrates. These include colchicine toxicity with colchicine; rhabdomyolysis with simvastatin, lovastatin and atorvastatin; and hypotension with calcium channel blockers metabolized by CYP3A4 (e.g., verapamil, amlodipine, diltiazem) (see PRECAUTIONS - Drug Interactions ). There have been post-marketing reports of colchicine toxicity with concomitant use of erythromycin and colchicine. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0277341c-8513-4317-9334-c242f97630c1$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$b4b5da1e-0b6c-4b0f-896b-da33f3087591$t$, $t$24947$t$, $t$ferrous sulfate$t$, $t$See symptoms on front panel. Relieves hot flashes with headaches *$t$, $t$Adults and children: At the onset of symptoms, dissolve 5 pellets under the tongue 3 times a day until symptoms are relieved or as directed by a doctor.$t$, null, $t$Stop use and ask a doctor if symptoms persist for more than 3 days or worsen.$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=3a749d62-0e20-0c15-e063-6394a90ac1a8$t$, now())
