insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$045e42e1-047f-4444-82f5-f869340bd381$t$, $t$4511$t$, $t$folic acid$t$, $t$Folic acid is effective in the treatment of megaloblastic anemias due to a deficiency of folic acid (as may be seen in tropical or nontropical sprue) and in anemias of nutritional origin, pregnancy, infancy, or childhood.$t$, $t$Oral administration is preferred. Although most patients with malabsorption cannot absorb food folates, they are able to absorb folic acid given orally. Parenteral administration is not advocated but may be necessary in some individuals (e.g., patients receiving parenteral or enteral alimentation). Doses greater than 0.1 mg should not be used unless anemia due to vitamin B 12 deficiency has been ruled out or is being adequately treated with a cobalamin. …$t$, $t$Administration of folic acid alone is improper therapy for pernicious anemia and other megaloblastic anemias in which vitamin B 12 is deficient.$t$, $t$Allergic sensitization has been reported following both oral and parenteral administration of folic acid. Folic acid is relatively nontoxic in man. Rare instances of allergic responses to folic acid preparations have been reported and have included erythema, skin rash, itching, general malaise, and respiratory difficulty due to bronchospasm. One patient experienced symptoms suggesting anaphylaxis following injection of the drug. …$t$, $t$Drug Interactions There is evidence that the anticonvulsant action of phenytoin is antagonized by folic acid. A patient whose epilepsy is completely controlled by phenytoin may require increased doses to prevent convulsions if folic acid is given. Folate deficiency may result from increased loss of folate, as in renal dialysis and/or interference with metabolism (e.g., folic acid antagonists such as methotrexate); the administration of anticonvulsants, such as diphenylhydantoin, primidone, and barbiturates; …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0b263a1e-260b-4775-a76e-766add336f12$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$e77d3080-6c4e-4b66-b5f3-52ccf43f1ba0$t$, $t$4603$t$, $t$furosemide$t$, $t$Edema Furosemide tablets are indicated in adults and pediatric patients for the treatment of edema associated with congestive heart failure, cirrhosis of the liver, and renal disease, including the nephrotic syndrome. Furosemide tablets are particularly useful when an agent with greater diuretic potential is desired. Hypertension Oral furosemide may be used in adults for the treatment of hypertension alone or in combination with other antihypertensive agents. …$t$, $t$Edema Therapy should be individualized according to patient response to gain maximal therapeutic response and to determine the minimal dose needed to maintain that response. Adults: The usual initial dose of furosemide tablets is 20 to 80 mg given as a single dose. Ordinarily a prompt diuresis ensues. If needed, the same dose can be administered 6 to 8 hours later or the dose may be increased. …$t$, $t$Furosemide is a potent diuretic which, if given in excessive amounts, can lead to a profound diuresis with water and electrolyte depletion. Therefore, careful medical supervision is required and dose and dose schedule must be adjusted to the individual patient's needs (see DOSAGE AND ADMINISTRATION ). WARNINGS In patients with hepatic cirrhosis and ascites, furosemide therapy is best initiated in the hospital. …$t$, $t$Adverse reactions are categorized below by organ system and listed by decreasing severity. Gastrointestinal System Reactions 1. hepatic encephalopathy in patients with hepatocellular insufficiency 2. pancreatitis 3. jaundice (intrahepatic cholestatic jaundice) 4. increased liver enzymes 5. anorexia 6. oral and gastric irritation 7. cramping 8. diarrhea 9. constipation 10. nausea 11. vomiting Systemic Hypersensitivity Reactions 1. severe anaphylactic or anaphylactoid reactions (e.g., with shock) 2. …$t$, $t$Drug Interactions Furosemide may increase the ototoxic potential of aminoglycoside antibiotics, especially in the presence of impaired renal function. Except in life-threatening situations, avoid this combination. Furosemide should not be used concomitantly with ethacrynic acid because of the possibility of ototoxicity. Patients receiving high doses of salicylates concomitantly with furosemide, as in rheumatic disease, may experience salicylate toxicity at lower doses because of competitive renal excretory sites. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=01a5f094-b473-4e46-9e61-69d5ec6dd766$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$4d1c7c78-6eac-425a-a68e-5cf38971e6c7$t$, $t$1596450$t$, $t$gentamicin$t$, $t$To reduce the development of drug-resistant bacteria and maintain the effectiveness of Gentamicin Sulfate in 0.9% Sodium Chloride Injection and other antibacterial drugs, Gentamicin Sulfate in 0.9% Sodium Chloride Injection should be used only to treat or prevent infections that are proven or strongly suspected to be caused by susceptible bacteria. When culture and susceptibility information are available, they should be considered in selecting or modifying antibacterial therapy. …$t$, $t$Gentamicin Sulfate in 0.9% Sodium Chloride Injection is for intravenous use only . The patient’s pretreatment body weight should be obtained for calculation of correct dosage. The dosage of aminoglycosides in obese patients should be based on an estimate of the lean body mass. It is desirable to limit the duration of treatment with aminoglycosides to short term. …$t$, $t$Patients treated with aminoglycosides should be under close clinical observation because of the potential toxicity associated with their use. As with other aminoglycosides, gentamicin sulfate is potentially nephrotoxic. The risk of nephrotoxicity is greater in patients with impaired renal function and in those who receive high dosage or prolonged therapy. …$t$, $t$Nephrotoxicity - Adverse renal effects, as demonstrated by the presence of casts, cells, or protein in the urine or by rising BUN, NPN, serum creatinine and oliguria, have been reported. They occur more frequently in patients with a history of renal impairment and in patients treated for longer periods or with larger dosages than recommended. …$t$, $t$Drug Interactions The concurrent use of gentamicin with potent diuretics, such as ethacrynic acid or furosemide, should be avoided, since certain diuretics by themselves may cause ototoxicity. In addition, when administered intravenously, diuretics may enhance aminoglycoside toxicity by altering the antibiotic concentration in serum and tissue. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=449c9a41-d61e-49fd-b5e3-d76f74b92acf$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$1b3ae831-bc09-447f-9d53-cf467c20b098$t$, $t$4815$t$, $t$glyburide$t$, $t$Glyburide tablets USP are indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus.$t$, $t$Patients should be retitrated when transferred from glyburide (micronized) tablets or other oral hypoglycemic agents (see PRECAUTIONS ). There is no fixed dosage regimen for the management of diabetes mellitus with glyburide tablets. In addition to the usual monitoring of urinary glucose, the patient’s blood glucose must also be monitored periodically to determine the minimum effective dose for the patient; to detect primary failure, i.e. …$t$, $t$The administration of oral hypoglycemic drugs has been reported to be associated with increased cardiovascular mortality as compared to treatment with diet alone or diet plus insulin. This warning is based on the study conducted by the University Group Diabetes Program (UGDP), a long-term prospective clinical trial designed to evaluate the effectiveness of glucose-lowering drugs in preventing or delaying vascular complications in patients with non-insulin-dependent diabetes. …$t$, $t$Hypoglycemia: See PRECAUTIONS and OVERDOSAGE Sections. Gastrointestinal Reactions: Cholestatic jaundice and hepatitis may occur rarely which may progress to liver failure; glyburide tablets should be discontinued if this occurs. Liver function abnormalities, including isolated transaminase elevations, have been reported. Gastrointestinal disturbances, e.g. , nausea, epigastric fullness, and heartburn are the most common reactions, having occurred in 1.8% of treated patients during clinical trials. …$t$, $t$Drug Interactions The hypoglycemic action of sulfonylureas may be potentiated by certain drugs including non-steroidal anti-inflammatory agents and other drugs that are highly protein bound, salicylates, sulfonamides, chloramphenicol, probenecid, coumarins, monoamine oxidase inhibitors, and beta adrenergic blocking agents. When such drugs are administered to a patient receiving glyburide, the patient should be observed closely for hypoglycemia. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=21786ac0-da3c-16cb-e063-6394a90a4596$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$0a5a7770-97ac-4590-b1bf-812ff3df5182$t$, $t$5487$t$, $t$hydrochlorothiazide$t$, $t$Olmesartan medoxomil and hydrochlorothiazide is indicated for the treatment of hypertension, to lower blood pressure. Olmesartan medoxomil and hydrochlorothiazide is not indicated for the initial therapy of hypertension . Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. …$t$, $t$The recommended starting dose of olmesartan medoxomil and hydrochlorothiazide is 40/12.5 mg once daily in patients whose blood pressure is not adequately controlled with olmesartan monotherapy. Dose can be titrated up to 40 /25 mg if necessary. The recommended starting dose of olmesartan medoxomil and hydrochlorothiazide is 20/12.5 mg once daily in patients whose blood pressure is not adequately controlled with HCT monotherapy or who experience dose-limiting adverse reactions with hydrochlorothiazide. …$t$, $t$WARNING: FETAL TOXICITY When pregnancy is detected, discontinue olmesartan medoxomil and hydrochlorothiazide as soon as possible . Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus . WARNING: FETAL TOXICITY See full prescribing information for complete boxed warning. When pregnancy is detected, discontinue olmesartan medoxomil and hydrochlorothiazide as soon as possible . …$t$, $t$The following adverse reactions with olmesartan medoxomil and hydrochlorothiazide are described elsewhere: Hypotension in Volume- or Salt-Depleted Patients Impaired Renal Function Hypersensitivity Reactions Electrolyte and Metabolic Imbalances Acute Myopia and Secondary Angle-Closure Glaucoma Systemic Lupus Erythematosus Sprue-Like Enteropathy Most common adverse reactions (incidence ≥2%) are nausea, hyperuricemia, dizziness, and upper respiratory infection 6.1 Clinical Trials Experience Because clinical studies …$t$, $t$Lithium: Risk of lithium toxicity Non-Steroidal Anti-Inflammatory Drugs (NSAIDs): Reduced diuretic, natriuretic and antihypotensive effects; increased risk of renal toxicity Dual inhibition of the renin-angiotensin system: Increased risk of renal impairment, hypotension, and hyperkalemia Colesevelam hydrochloride: Consider administering olmesartan at least 4 hours before colesevelam hydrochloride dose Antidiabetic drugs: Dosage adjustment may be required Cholestyramine and colestipol: Reduced absorption of …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=017bc6a3-5b3d-2381-e063-6394a90abece$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$84dc1588-f24c-49df-826b-035b95e8c266$t$, $t$5492$t$, $t$hydrocortisone$t$, $t$Cortifoam ® is indicated as adjunctive therapy in the topical treatment of ulcerative proctitis of the distal portion of the rectum in patients who cannot retain hydrocortisone or other corticosteroid enemas.$t$, $t$The usual dose is one applicatorful once or twice daily for two or three weeks, and every second day thereafter, administered rectally. Directions for use, below and on the carton, describe how to use the aerosol container and applicator. Satisfactory response usually occurs within five to seven days marked by a decrease in symptoms. Symptomatic improvement in ulcerative proctitis should not be used as the sole criterion for evaluating efficacy. …$t$, $t$General Do not insert any part of the aerosol container directly into the anus. Contents of the container are under pressure. Do not burn or puncture the aerosol container. Do not store at temperatures above 120°F. Because Cortifoam ® is not expelled, systemic hydrocortisone absorption may be greater from Cortifoam ® than from corticosteroid enema formulations. …$t$, $t$ADVERSE REACTIONS (listed alphabetically, under each subsection) Allergic reactions: Anaphylactoid reaction, anaphylaxis, angioedema. Cardiovascular: Bradycardia, cardiac arrest, cardiac arrhythmias, cardiac enlargement, circulatory collapse, congestive heart failure, fat embolism, hypertension, hypertrophic cardiomyopathy in premature infants, myocardial rupture following recent myocardial infarction (see WARNINGS ), pulmonary edema, syncope, tachycardia, thromboembolism, thrombophlebitis, vasculitis. …$t$, $t$Drug Interactions Aminoglutethimide: Aminoglutethimide may lead to a loss of corticosteroid-induced adrenal suppression. Amphotericin B injection and potassium-depleting agents: When corticosteroids are administered concomitantly with potassium-depleting agents (i.e., amphotericin B, diuretics), patients should be observed closely for development of hypokalemia. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0093b694-9fcb-46ae-b1ab-7d0fa204c6c8$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$c8295fe8-969f-4d43-bc63-fcfa827dce4b$t$, $t$5640$t$, $t$ibuprofen$t$, $t$Carefully consider the potential benefits and risks of ibuprofen tablets and other treatment options before deciding to use ibuprofen. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals (see WARNINGS ). Ibuprofen tablets are indicated for relief of the signs and symptoms of rheumatoid arthritis and osteoarthritis. Ibuprofen tablets are indicated for relief of mild to moderate pain. …$t$, $t$Carefully consider the potential benefits and risks of ibuprofen tablets and other treatment options before deciding to use ibuprofen tablets. Use the lowest effective dose for the shortest duration consistent with individual patient treatment goals (see WARNINGS ). After observing the response to initial therapy with ibuprofen tablets, the dose and frequency should be adjusted to suit an individual patient's needs. Do not exceed 3200 mg total daily dose. …$t$, $t$Cardiovascular Thrombotic Events Nonsteroidal anti-inflammatory drugs (NSAIDs) cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use . Ibuprofen tablets are contraindicated in the setting of coronary artery bypass graft (CABG) surgery . …$t$, $t$The most frequent type of adverse reaction occurring with ibuprofen tablets is gastrointestinal. In controlled clinical trials the percentage of patients reporting one or more gastrointestinal complaints ranged from 4% to 16%. In controlled studies when ibuprofen tablets were compared to aspirin and indomethacin in equally effective doses, the overall incidence of gastrointestinal complaints was about half that seen in either the aspirin- or indomethacin-treated patients. …$t$, $t$Preexisting asthma Patients with asthma may have aspirin-sensitive asthma. The use of aspirin in patients with aspirin-sensitive asthma has been associated with severe bronchospasm, which can be fatal. Since cross reactivity, including bronchospasm, between aspirin and NSAIDs has been reported in such aspirin-sensitive patients, ibuprofen tablets should not be administered to patients with this form of aspirin sensitivity and should be used with caution in patients with preexisting asthma.$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=00872852-680a-41b3-901b-b991b12a176d$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$e915bf78-71d9-4463-8648-63823f82be87$t$, $t$6038$t$, $t$isoniazid$t$, $t$Isoniazid tablets, USP are recommended for all forms of tuberculosis in which organisms are susceptible. However, active tuberculosis must be treated with multiple concomitant anti-tuberculosis medications to prevent the emergence of drug resistance. Single-drug treatment of active tuberculosis with isoniazid or any other medication, is inadequate therapy. Isoniazid tablets, USP are recommended as preventive therapy for the following groups, regardless of age. …$t$, $t$DOSAGE AND ADMINISTRATION (See also INDICATIONS AND USAGE ) NOTE For preventive therapy of tuberculous infection and treatment of tuberculosis, it is recommended that physicians be familiar with the following publications: the recommendations of the Advisory Council for the Elimination of Tuberculosis, published in the MMWR: vol 42; RR-4, 1993 and Treatment of Tuberculosis and Tuberculosis Infection in Adults and Children, American Journal of Respiratory and Critical Care Medicine: vol 149; 1359-1374, 1994. …$t$, $t$Severe and sometimes fatal hepatitis associated with isoniazid therapy has been reported and may occur or may develop even after many months of treatment. The risk of developing hepatitis is age related. Approximate case rates by age are: less than 1 per 1,000 for persons under 20 years of age, 3 per 1,000 for persons in the 20 to 34 year age group, 12 per 1,000 for persons in the 35 to 49 year age group, 23 per 1,000 for persons in the 50 to 64 year age group and 8 per 1,000 for persons over 65 years of age. …$t$, $t$The most frequent reactions are those affecting the nervous system and the liver. Nervous System Reactions Peripheral neuropathy is the most common toxic effect. It is dose-related, occurs most often in the malnourished and in those predisposed to neuritis (e.g., alcoholics and diabetics) and is usually preceded by paresthesias of the feet and hands. The incidence is higher in "slow inactivators". …$t$, $t$Drug Interactions Food Isoniazid should not be administered with food. Studies have shown that the bioavailability of isoniazid is reduced significantly when administered with food. Tyramine- and histamine-containing foods should be avoided in patients receiving isoniazid. Because isoniazid has some monoamine oxidase inhibiting activity, an interaction with tyramine-containing foods (cheese, red wine) may occur. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=03bf3bd5-64f9-4491-89fd-96c5c10d0129$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$80a19f5a-41a7-4f2f-a4a9-72ba92737c74$t$, $t$6468$t$, $t$loperamide$t$, $t$Loperamide hydrochloride capsules are indicated for the control and symptomatic relief of acute nonspecific diarrhea in patients 2 years of age and older and of chronic diarrhea in adults associated with inflammatory bowel disease. Loperamide hydrochloride capsules are also indicated for reducing the volume of discharge from ileostomies.$t$, $t$Loperamide hydrochloride capsules USP are contraindicated in pediatric patients less than 2 years of age due to the risks of respiratory depression and serious cardiac adverse reactions (see CONTRAINDICATIONS ). Avoid loperamide hydrochloride capsules dosages higher than recommended in adult or pediatric patients 2 years of age and older due to the risk of serious cardiac adverse reactions (see WARNINGS , OVERDOSAGE ). …$t$, $t$WARNING: TORSADES DE POINTES AND SUDDEN DEATH Cases of Torsades de Pointes, cardiac arrest, and death have been reported with the use of a higher than recommended dosage of loperamide hydrochloride capsules (see WARNINGS and OVERDOSAGE ). Loperamide hydrochloride capsules are contraindicated in pediatric patients less than 2 years of age (see CONTRAINDICATIONS ). …$t$, $t$Clinical Trial Experience The adverse effects reported during clinical investigations of loperamide hydrochloride capsules are difficult to distinguish from symptoms associated with the diarrheal syndrome. Adverse experiences recorded during clinical studies with loperamide hydrochloride capsules were generally of a minor and self-limiting nature. They were more commonly observed during the treatment of chronic diarrhea. …$t$, $t$Drug Interactions Effects of Other Drugs on Loperamide Concomitant use of loperamide hydrochloride capsules with inhibitors of CYP3A4 (e.g., itraconazole) or CYP2C8 (e.g., gemfibrozil) or inhibitors of P-glycoprotein (e.g., quinidine, ritonavir) can increase exposure to loperamide. The increased systemic exposure to loperamide may increase a risk for cardiac adverse reactions especially in patients who are taking multiple CYP enzyme inhibitors, or in patients with underlying cardiac conditions (see WARNINGS ). …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=03c907d5-87f8-47a6-9544-5a24f5272739$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$b01a7ee1-e826-4159-841a-be3f29f13474$t$, $t$28889$t$, $t$loratadine$t$, $t$Temporarily relieves these symptoms due to hay fever or other respiratory allergies: runny nose sneezing itchy, watery eyes itching of the nose or throat$t$, $t$Adults and children 6 years of age and over 1 tablet daily; not more than 1 tablet in 24 hours children under 6 years of age ask a doctor consumers with liver or kidney disease ask a doctor$t$, $t$Drug Facts$t$, $t$Stop use and ask a doctor if an allergic reaction to this product occurs. Seek medical help right away.$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=01cb43cf-57a9-f189-e063-6294a90afd88$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$fa1c38db-167c-49de-9ae1-b59517fcc40c$t$, $t$52175$t$, $t$losartan$t$, $t$Losartan potassium tablets are an angiotensin II receptor blocker (ARB) indicated for: • Treatment of hypertension, to lower blood pressure in adults and children greater than 6 years old. Lowering blood pressure reduces the risk of fatal and nonfatal cardiovascular events, primarily strokes and myocardial infarctions. • Reduction of the risk of stroke in patients with hypertension and left ventricular hypertrophy. There is evidence that this benefit does not apply to Black patients. …$t$, $t$Hypertension • Usual adult dose: 50 mg once daily. • Usual pediatric starting dose: 0.7 mg per kg once daily (up to 50 mg). Hypertensive Patients with Left Ventricular Hypertrophy • Usual starting dose: 50 mg once daily. • Add hydrochlorothiazide 12.5 mg and/or increase losartan potassium to 100 mg followed by an increase to hydrochlorothiazide 25 mg if further blood pressure response is needed. Nephropathy in Type 2 Diabetic Patients • Usual dose: 50 mg once daily. …$t$, $t$WARNING: FETAL TOXICITY When pregnancy is detected, discontinue losartan potassium as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus . WARNING: FETAL TOXICITY See full prescribing information for complete boxed warning. When pregnancy is detected, discontinue losartan potassium as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus.$t$, $t$Most common adverse reactions (incidence ≥2% and greater than placebo) are: dizziness, upper respiratory infection, nasal congestion, and back pain. 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in practice. …$t$, $t$7 DRUG INTERACTIONS • Agents Increasing Serum Potassium: Risk of hyperkalemia. • Lithium: Risk of lithium toxicity. • NSAIDs: Increased risk of renal impairment and reduced diuretic, natriuretic, and antihypertensive effects. • Dual Inhibition of the Renin-Angiotensin System: Increased risk of renal impairment, hypotension, syncope, and hyperkalemia. 7.1 Agents Increasing Serum Potassium Coadministration of losartan with other drugs that raise serum potassium levels may result in hyperkalemia. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=021cd76a-b093-4704-8410-5e7d01e20a54$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$e6801dbe-0a34-495b-b20c-29776f296830$t$, $t$6585$t$, $t$magnesium sulfate$t$, $t$Magnesium Sulfate in 5% Dextrose Injection is indicated for: • Prevention of eclampsia in patients with preeclampsia • Treatment of seizures and prevention of recurrent seizures in patients with eclampsia Magnesium Sulfate in 5% Dextrose Injection is indicated for : • Prevention of eclampsia in patients with preeclampsia • Treatment of seizures and prevention of recurrent seizures in patients with eclampsia$t$, $t$2 DOSAGE AND ADMINISTRATION • Administer via intravenous infusion pump • Recommended loading dosage is 4 to 6 grams over 15 minutes followed by a recommended maintenance dosage of 1 to 2 grams every hour; maximum recommended dosage is 30 to 40 grams over 24 hours • Obtain serum magnesium concentrations and assess clinical status to adjust the dose • Administration beyond 5 to 7 days is not recommended • In patients with severe renal impairment and/or urine output less than 0.5 mL/kg/hour, administer a 4 gram …$t$, $t$5 WARNINGS AND PRECAUTIONS • Fetal-neonatal toxicity with prolonged use : Administration beyond 5 to 7 days is not recommended and can lead to hypocalcemia and bone abnormalities • Risk of magnesium toxicity : Monitor magnesium concentrations and clinical signs of magnesium toxicity including respiratory depression, an injectable calcium salt should be immediately available to counteract hazards, for significant toxicity stop Magnesium Sulfate in 5% Dextrose Injection • Risk of elevated blood glucose: Solutions …$t$, $t$The following adverse reactions have been identified in clinical studies or postmarketing reports. Because these reactions are reported voluntarily from a population of uncertain size, it is not always possible to reliably estimate their frequency or establish a causal relationship to drug exposure. …$t$, $t$Table 1 presents the potential clinical impact of medications that may be commonly administered concomitantly with Magnesium Sulfate in 5% Dextrose Injection in the clinical setting. Table 1: Potential Clinically Significant Drug Interactions with Magnesium Sulfate in 5% Dextrose Injection For drug incompatibility information . …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=03ebeabb-8386-4af4-3086-bdf3c3fc4a5a$t$, now())
