insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$12748384-dcfd-40a2-9fc2-3baabf39dc18$t$, $t$6809$t$, $t$metformin$t$, $t$Metformin hydrochloride tablets are indicated as an adjunct to diet and exercise to improve glycemic control in adults and pediatric patients 10 years of age and older with type 2 diabetes mellitus. Metformin hydrochloride tablets are biguanide indicated as an adjunct to diet and exercise to improve glycemic control in adults and pediatric patients 10 years of age and older with type 2 diabetes mellitus.$t$, $t$Adult Dosage for metformin hydrochloride tablets: Starting dose: 500 mg orally twice a day or 850 mg once a day, with meals Increase the dose in increments of 500 mg weekly or 850 mg every 2 weeks, up to a maximum dose of 2550 mg per day, given in divided doses Doses above 2000 mg may be better tolerated given 3 times a day with meals Pediatric Dosage for metformin hydrochloride tablets: Starting dose: 500 mg orally twice a day, with meals Increase dosage in increments of 500 mg weekly up to a maximum of 2000 mg …$t$, $t$BOXED WARNING WARNING: LACTIC ACIDOSIS Postmarketing cases of metformin-associated lactic acidosis have resulted in death, hypothermia, hypotension, and resistant bradyarrhythmias. The onset of metformin­ associated lactic acidosis is often subtle, accompanied only by nonspecific symptoms such as malaise, myalgias, respiratory distress, somnolence, and abdominal pain. …$t$, $t$Lactic Acidosis . Vitamin B12 Deficiency . Hypoglycemia [ see Warnings and Precautions For metformin hydrochloride tablets, the most common adverse reactions (>5.0%) are diarrhea, nausea/vomiting, flatulence, asthenia, indigestion, abdominal discomfort, and headache. …$t$, $t$Table 3 presents clinically significant drug interactions with metformin hydrochloride tablets. Table 3: Clinically Significant Drug Interactions with Metformin Hydrochloride Tablets Carbonic Anhydrase Inhibitors Clinical Impact: Carbonic anhydrase inhibitors frequently cause a decrease in serum bicarbonate and induce non-anion gap, hyperchloremic metabolic acidosis. Concomitant use of these drugs with metformin hydrochloride tablets may increase the risk for lactic acidosis. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=011de1a5-1ac0-4831-9e8d-26ec79ba2205$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$050b3350-09b4-4870-baea-95f5cec06797$t$, $t$6915$t$, $t$metoclopramide$t$, $t$The use of Metoclopramide Oral Solution is recommended for adults only. Therapy should not exceed 12 weeks in duration. Symptomatic Gastroesophageal Reflux Metoclopramide Oral Solution is indicated as short-term (4 to 12 weeks) therapy for adults with symptomatic, documented gastroesophageal reflux who fail to respond to conventional therapy. The principal effect of metoclopramide is on symptoms of post-prandial and daytime heartburn with less observed effect on nocturnal symptoms. …$t$, $t$Therapy with metoclopramide oral solution should not exceed 12 weeks in duration. For the Relief of Symptomatic Gastroesophageal Reflux Administer from 10 mg to 15 mg metoclopramide orally up to 4 times daily 30 minutes before each meal and at bedtime, depending upon symptoms being treated and clinical response (see CLINICAL PHARMACOLOGY and INDICATIONS AND USAGE ). …$t$, $t$WARNING: TARDIVE DYSKINESIA Treatment with metoclopramide can cause tardive dyskinesia, a serious movement disorder that is often irreversible. The risk of developing tardive dyskinesia increases with duration of treatment and total cumulative dose. Metoclopramide therapy should be discontinued in patients who develop signs or symptoms of tardive dyskinesia. There is no known treatment for tardive dyskinesia. In some patients, symptoms may lessen or resolve after metoclopramide treatment is stopped. …$t$, $t$In general, the incidence of adverse reactions correlates with the dose and duration of metoclopramide administration. The following reactions have been reported, although in most instances, data do not permit an estimate of frequency: CNS Effects Restlessness, drowsiness, fatigue, and lassitude occur in approximately 10% of patients receiving the most commonly prescribed dosage of 10 mg 4 times daily. (see PRECAUTIONS ). …$t$, $t$Drug Interactions The effects of metoclopramide on gastrointestinal motility are antagonized by anticholinergic drugs and narcotic analgesics. Additive sedative effects can occur when metoclopramide is given with alcohol, sedatives, hypnotics, narcotics, or tranquilizers. The finding that metoclopramide releases catecholamines in patients with essential hypertension suggests that it should be used cautiously, if at all, in patients receiving monoamine oxidase inhibitors. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0034a97a-fb05-418a-a234-de278907cd2a$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$827e0027-469c-4ddd-9627-82eee88629b8$t$, $t$6922$t$, $t$metronidazole$t$, $t$Symptomatic Trichomoniasis. Metronidazole tablets are indicated for the treatment of T. vaginalis infection in females and males when the presence of the trichomonad has been confirmed by appropriate laboratory procedures (wet smears and/or cultures). Asymptomatic Trichomoniasis. Metronidazole tablets are indicated in the treatment of asymptomatic T. vaginalis infection in females when the organism is associated with endocervicitis, cervicitis, or cervical erosion. …$t$, $t$Trichomoniasis: In the Female: One-day treatment − two grams of metronidazole tablets, given either as a single dose or in two divided doses of one gram each, given in the same day. Seven-day course of treatment − 250 mg three times daily for seven consecutive days. There is some indication from controlled comparative studies that cure rates as determined by vaginal smears and signs and symptoms, may be higher after a seven-day course of treatment than after a one-day treatment regimen. …$t$, $t$Metronidazole has been shown to be carcinogenic in mice and rats (see PRECAUTIONS ). Unnecessary use of the drug should be avoided. Its use should be reserved for the conditions described in the INDICATIONS AND USAGE section below.$t$, $t$The following reactions have been reported during treatment with metronidazole: Central Nervous System: The most serious adverse reactions reported in patients treated with metronidazole have been convulsive seizures, encephalopathy, aseptic meningitis, optic and peripheral neuropathy, the latter characterized mainly by numbness or paresthesia of an extremity. …$t$, $t$Drug Interactions Disulfiram Psychotic reactions have been reported in alcoholic patients who are using metronidazole and disulfiram concurrently. Metronidazole should not be given to patients who have taken disulfiram within the last two weeks (see CONTRAINDICATIONS ). Alcoholic Beverages Abdominal cramps, nausea, vomiting, headaches, and flushing may occur if alcoholic beverages or products containing propylene glycol are consumed during or following metronidazole therapy (see CONTRAINDICATIONS ). …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=02046a22-a5eb-4bb7-bec7-e5a2aa55e142$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$bc38c9ad-f136-4439-a517-27b05a52a3d1$t$, $t$42331$t$, $t$misoprostol$t$, $t$Diclofenac sodium and misoprostol delayed-release tablets are indicated for treatment of the signs and symptoms of osteoarthritis or rheumatoid arthritis in adult patients at high risk of developing NSAID-induced gastric and duodenal ulcers and their complications. For a list of factors that may increase the risk of NSAID-induced gastric and duodenal ulcers and their complications . …$t$, $t$The lowest effective dosage for the shortest duration consistent with individual patient treatment goals. Osteoarthritis: The recommended dosage for maximal GI protection is one tablet (containing 50 mg of diclofenac and 200 mcg of misoprostol) three times daily. A dosage of diclofenac higher than 150 mg/day is not recommended. Rheumatoid Arthritis: The recommended dosage for maximal GI protection is one tablet (containing 50 mg of diclofenac and 200 mcg of misoprostol) three or four times daily. …$t$, $t$WARNING: RISK OF UTERINE RUPTURE, ABORTION, PREMATURE BIRTH, BIRTH DEFECTS; SERIOUS CARDIOVASCULAR EVENTS; AND SERIOUS GASTROINTESTINAL EVENTS Uterine Rupture, Abortion, Premature Birth, and Birth Defects Administration of misoprostol, a component of diclofenac sodium and misoprostol delayed-release tablets , to pregnant women can cause uterine rupture, abortion, premature birth, or birth defects. Uterine rupture has occurred when misoprostol was administered in pregnant women to induce labor or an abortion . …$t$, $t$Cardiovascular Thrombotic Events GI Bleeding, Ulceration and Perforation Hepatotoxicity Hypertension Heart Failure and Edema Renal Toxicity and Hyperkalemia Anaphylactic Reactions Serious Skin Reactions Hematologic Toxicity Most common adverse reactions (>2%) are: abdominal pain, diarrhea, dyspepsia, nausea, flatulence, gastritis, vomiting, constipation, headache, dizziness, alanine aminotransferase increased, hematocrit decreased 6.1 Clinical Trials Experience Because clinical trials are conducted under widely …$t$, $t$See Table 1 for clinically significant drug interactions with diclofenac and misoprostol. Table 1: Clinically Significant Drug Interactions with Diclofenac and Misoprostol Drugs That Interfere with Hemostasis Clinical Impact: Diclofenac and anticoagulants such as warfarin have a synergistic effect on bleeding. The concomitant use of diclofenac and anticoagulants have an increased risk of serious bleeding compared to the use of either drug alone. Serotonin release by platelets plays an important role in hemostasis. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0d6509a1-7af8-473b-8951-c19439274379$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$bb089d04-962d-44ae-b8a8-b44e314d9603$t$, $t$7052$t$, $t$morphine$t$, $t$Morphine Sulfate Injection is indicated for the management of pain severe enough to require use of an opioid analgesic by Patient Controlled Analgesia (PCA), and for which alternative treatments are inadequate. Limitations of Use Preservative-free Morphine Sulfate Injection is for administration via a compatible Alaris ® infusion device. …$t$, $t$The lowest effective dosage for the shortest duration consistent with individual patient treatment goals. Individualize dosing based on the severity of pain, patient response, prior analgesic experience, and risk factors for addiction, abuse, and misuse. Intravenous Adult Dosage: The usual dose for administration to adults, via a compatible Alaris ® infusion device, is a 1 mg bolus, with a range of 0.2 to 3 mg per incremental dose. The recommended Lockout Interval is 6 minutes. …$t$, $t$WARNING: ADDICTION, ABUSE, AND MISUSE; LIFE-THREATENING RESPIRATORY DEPRESSION; NEONATAL OPIOID WITHDRAWAL SYNDROME; and RISKS FROM CONCOMITANT USE WITH BENZODIAZEPINES OR OTHER CNS DEPRESSANTS Addiction, Abuse, and Misuse Morphine Sulfate Injection exposes patients and other users to the risks of opioid addiction, abuse, and misuse, which can lead to overdose and death. …$t$, $t$The following serious adverse reactions are described, or described in greater detail, in other sections: Addiction, Abuse, and Misuse Life-Threatening Respiratory Depression Neonatal Opioid Withdrawal Syndrome Interactions with Benzodiazepines or Other CNS Depressants Cardiovascular Instability Adrenal Insufficiency Severe Hypotension Gastrointestinal Adverse Reactions Seizures Withdrawal The following adverse reactions associated with the use of morphine were identified in clinical studies or postmarketing …$t$, $t$Table 1 includes clinically significant drug interactions with Morphine Sulfate Injection. Table 1: Clinically Significant Drug Interactions with Morphine Sulfate Injection Benzodiazepines and Central Nervous System (CNS) Depressants Clinical Impact: Due to additive pharmacologic effect, the concomitant use of benzodiazepines or other CNS depressants, including alcohol, can increase the risk of hypotension, respiratory depression, profound sedation, coma, and death. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=1034467f-d436-4b87-a902-c7e8885daa8a$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$10b7fda5-7b70-4680-9e7b-aaaada822dc1$t$, $t$7417$t$, $t$nifedipine$t$, $t$Nifedipine extended-release tablets are indicated for the treatment of hypertension. It may be used alone or in combination with other antihypertensive agents.$t$, $t$Dosage should be adjusted according to each patient’s needs. It is recommended that nifedipine extended-release tablet be administered orally once daily on an empty stomach. Nifedipine extended-release tablet is an extended-release dosage form and tablets should be swallowed whole, not bitten or divided. In general, titration should proceed over a 7-14 day period starting with 30 mg once daily. Upward titration should be based on therapeutic efficacy and safety. …$t$, $t$Excessive Hypotension Although in most patients the hypotensive effect of nifedipine is modest and well tolerated, occasional patients have had excessive and poorly tolerated hypotension. These responses have usually occurred during initial titration or at the time of subsequent upward dosage adjustment, and may be more likely in patients using concomitant beta-blockers. …$t$, $t$The incidence of adverse events during treatment with nifedipine extended-release tablets in doses up to 90 mg daily were derived from multi-center placebo-controlled clinical trials in 370 hypertensive patients. Atenolol 50 mg once daily was used concomitantly in 187 of the 370 patients on nifedipine extended-release tablets and in 64 of the 126 patients on placebo. …$t$, $t$Drug Interactions Nifedipine is mainly eliminated by metabolism and is a substrate of CYP3A. Inhibitors and inducers of CYP3A can impact the exposure to nifedipine and consequently its desirable and undesirable effects. In vitro and in vivo data indicate that nifedipine can inhibit the metabolism of drugs that are substrates of CYP3A, thereby increasing the exposure to other drugs. Nifedipine is a vasodilator, and co-administration of other drugs affecting blood pressure may result in pharmacodynamic interactions. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0b4e9bbc-4c16-4611-9ea2-903852804227$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$a62099f6-cead-460e-983b-d1414e77f68b$t$, $t$9863$t$, $t$sodium chloride$t$, $t$Esmolol hydrochloride in sodium chloride injection is a beta adrenergic blocker indicated for the short-term treatment of: • Control of ventricular rate in supraventricular tachycardia including atrial fibrillation and atrial flutter and control of heart rate in noncompensatory sinus tachycardia • Control of perioperative tachycardia and hypertension 1.1 Supraventricular Tachycardia or Noncompensatory Sinus Tachycardia Esmolol hydrochloride in sodium chloride injection is indicated for the rapid control of …$t$, $t$2 DOSAGE AND ADMINISTRATION • Administer intravenously • Titrate using ventricular rate or blood pressure at ≥ 4-minute intervals • Supraventricular tachycardia (SVT) or noncompensatory sinus tachycardia o Optional loading dose: 500 mcg per kg infused over one minute o Then 50 mcg per kg per minute for the next 4 minutes o Adjust dose as needed to a maximum of 200 mcg per kg per minute o Additional loading doses may be administered • Perioperative tachycardia and hypertension o Loading dose: 500 mcg per kg over 1 …$t$, $t$5 WARNINGS AND PRECAUTIONS • Risk of hypotension, bradycardia, and cardiac failure: Monitor for signs and symptoms of cardiovascular adverse effects. Reduce or discontinue use • Risk of exacerbating reactive airway disease • Diabetes: May mask symptoms of hypoglycemia and alter glucose levels; …$t$, $t$Most common adverse reactions (incidence >10%) are symptomatic hypotension (hyperhidrosis, dizziness) and asymptomatic hypotension 6.1 Clinical Trials Experience Because clinical trials are conducted under widely varying conditions, adverse reaction rates observed in the clinical trials of a drug cannot be directly compared to rates in the clinical trials of another drug and may not reflect the rates observed in clinical practice. …$t$, $t$Concomitant use of esmolol hydrochloride in sodium chloride injection with other drugs that can lower blood pressure, reduce myocardial contractility, or interfere with sinus node function or electrical impulse propagation in the myocardium can exaggerate esmolol hydrochloride in sodium chloride injection’s effects on blood pressure, contractility, and impulse propagation. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=01ad7942-99c3-40ee-9cfb-272fb6c44e2b$t$, now())
