insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$a56ed025-b19f-4575-9532-0971503be488$t$, $t$33199$t$, $t$permethrin$t$, $t$Treats head lice$t$, $t$Inspect • all household members should be checked by another person for lice and/or nits (eggs) • use a magnifying glass in bright light to help you see the lice and nits (eggs) • use a tool, such as a comb or two unsharpened pencils to lift and part the hair • look for tiny nits near the scalp, beginning at the back of the neck and behind the ears • small sections of hair (1-2 inches wide) should be examined at a time • unlike dandruff, nits stick to the hair. Dandruff should move when lightly touched. …$t$, $t$For external use only Do not use • on children under 2 months of age • near the eyes • inside the nose, ear, mouth, or vagina • on lice in eyebrows or eyelashes. See your doctor. Ask a doctor before use if you are • allergic to ragweed. May cause breathing difficulty or an asthmatic episode. …$t$, $t$Stop use and see a doctor if • breathing difficulty occurs • eye irritation occurs • skin or scalp irritation continues or infection occurs$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=056fb377-34dd-4d33-83d7-c895b105f574$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$9e427fa1-c69e-44ff-809e-aaad29990398$t$, $t$8638$t$, $t$prednisolone$t$, $t$Prednisolone Sodium Phosphate Oral Solution (15 mg Prednisolone per 5 mL) is indicated in the following conditions: 1. Allergic States Control of severe or incapacitating allergic conditions intractable to adequate trials of conventional treatment in adult and pediatric populations with: seasonal or perennial allergic rhinitis; asthma; contact dermatitis; atopic dermatitis; serum sickness; drug hypersensitivity reactions. 2. Dermatologic Diseases Pemphigus; bullous dermatitis herpetiformis; …$t$, $t$The initial dosage of Prednisolone Sodium Phosphate Oral Solution (15 mg Prednisolone per 5 mL) may vary from 1.67 mL to 20 mL (5 to 60 mg prednisolone base) per day depending on the specific disease entity being treated. In situations of less severity, lower doses will generally suffice while in selected patients higher initial doses may be required. The initial dosage should be maintained or adjusted until a satisfactory response is noted. …$t$, $t$General In patients on corticosteroid therapy subjected to unusual stress, increased dosage of rapidly acting corticosteroids before, during and after the stressful situation is indicated. Cardio-renal Average and large doses of hydrocortisone or cortisone can cause elevation of blood pressure, salt and water retention, and increased excretion of potassium. These effects are less likely to occur with the synthetic derivatives except when used in large doses. …$t$, $t$ADVERSE REACTIONS (listed alphabetically under each subsection) Cardiovascular: Hypertrophic cardiomyopathy in premature infants. Dermatologic: Facial erythema; increased sweating; impaired wound healing; may suppress reactions to skin tests; petechiae and ecchymoses; thin fragile skin; urticaria; edema. Endocrine: Decreased carbohydrate tolerance; development of cushingoid state; hirsutism; increased requirements for insulin or oral hypoglycemic agents in diabetic patients; …$t$, $t$Drug Interactions Drugs such as barbiturates, phenytoin, ephedrine, and rifampin, which induce hepatic microsomal drug metabolizing enzyme activity may enhance metabolism of prednisolone and require that the dosage of Prednisolone Sodium Phosphate Oral Solution (15 mg Prednisolone per 5 mL) be increased. Increased activity of both cyclosporin and corticosteroids may occur when the two are used concurrently. Convulsions have been reported with this concurrent use. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=14b7f41b-4df1-42cb-bd1b-c74b28de2670$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$fce43982-a8ec-4dd8-bd59-f8e34b7884cc$t$, $t$7514$t$, $t$norethindrone$t$, $t$INDICATIONS AND USAGE 1. Indications Progestin-only oral contraceptives are indicated for the prevention of pregnancy. 2. Efficacy If used perfectly, the first-year failure rate for progestin-only oral contraceptives is 0.3%. However, the typical failure rate is estimated to be closer to 9%, due to late or omitted pills. Table 1 lists the pregnancy rates for users of all major methods of contraception. …$t$, $t$To achieve maximum contraceptive effectiveness, norethindrone tablets must be taken exactly as directed. One tablet is taken every day, at the same time. Administration is continuous, with no interruption between pill packs. See Detailed Patient Labeling for detailed instruction.$t$, $t$Cigarette smoking increases the risk of serious cardiovascular disease. Women who use oral contraceptives should be strongly advised not to smoke. Norethindrone tablets do not contain estrogen and, therefore, this insert does not discuss the serious health risks that have been associated with the estrogen component of combined oral contraceptives (COCs). The healthcare professional is referred to the prescribing information of combined oral contraceptives for a discussion of those risks. …$t$, $t$Adverse reactions reported with the use of POPs include: • Menstrual irregularity is the most frequently reported side effect. • Frequent and irregular bleeding are common, while long duration of bleeding episodes and amenorrhea are less likely. • Headache, breast tenderness, nausea, and dizziness are increased among progestin-only oral contraceptive users in some studies. • Androgenic side effects such as acne, hirsutism, and weight gain occur rarely. …$t$, $t$4. Drug Interactions Consult the labeling of concurrently-used drugs to obtain further information about interactions with hormonal contraceptives or the potential for enzyme alterations. • Effects of Other Drugs on Hormonal Contraceptives Substances decreasing the systemic concentrations of hormonal contraceptives (HCs) and potentially diminishing the efficacy of HCs: Drugs or herbal products that induce certain enzymes, including cytochrome P450 3A4 (CYP3A4), may decrease the systemic concentrations of HCs and …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=0d2f8fea-3675-40d2-afd9-9fcb148dbd4b$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$73c49b3c-0adc-41bd-ab02-25016034b5ee$t$, $t$9071$t$, $t$quinine$t$, $t$Quinine sulfate capsule USP is a cinchona alkaloid indicated for treatment of uncomplicated Plasmodium falciparum malaria . Quinine sulfate capsule USP is an antimalarial drug indicated only for treatment of uncomplicated Plasmodium falciparum malaria. Quinine sulfate has been shown to be effective in geographical regions where resistance to chloroquine has been documented . Quinine sulfate capsules USP are not approved for: Treatment of severe or complicated P. falciparum malaria. Prevention of malaria. …$t$, $t$Adults (≥ 16 years of age): 648 mg (two capsules) every 8 hours for 7 days . Patients with severe chronic renal impairment: one loading dose of 648 mg (two capsules) followed 12 hours later by 324 mg (one capsule) every 12 hours for 7 days . 2.1 Treatment of Uncomplicated P. falciparum Malaria For treatment of uncomplicated P. falciparum malaria in adults: Orally, 648 mg (two capsules) every 8 hours for 7 days . Quinine sulfate capsules USP should be taken with food to minimize gastric upset . …$t$, $t$WARNING: HEMATOLOGIC REACTIONS Quinine sulfate capsules use for the treatment or prevention of nocturnal leg cramps may result in serious and life-threatening hematologic reactions, including thrombocytopenia and hemolytic uremic syndrome/thrombotic thrombocytopenic purpura (HUS/TTP). Chronic renal impairment associated with the development of TTP has been reported. …$t$, $t$Most common adverse reactions are a cluster of symptoms called "cinchonism", which occurs to some degree in almost all patients taking quinine: headache, vasodilation and sweating, nausea, tinnitus, hearing impairment, vertigo or dizziness, blurred vision, disturbance in color perception, vomiting, diarrhea, abdominal pain, deafness, blindness, and disturbances in cardiac rhythm or conduction . 6.1 Overall Quinine can adversely affect almost every body system. …$t$, $t$Interacting Drug Interaction Drugs known to prolong QT interval (e.g., Class IA and Class III antiarrhythmic agents). Quinine sulfate prolongs QT interval, ECG abnormalities including QT prolongation and Torsades de Pointes. Avoid concomitant use . Other antimalarials (e.g., halofantrine, mefloquine). ECG abnormalities including QT prolongation Avoid concomitant use . CYP3A4 inducers or inhibitors Alteration in plasma quinine concentration. Monitor for lack of efficacy or increased adverse events of quinine . …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=1f32f05c-a215-40be-b951-e41a7b54a8a0$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$75a89d5a-9c59-4f8a-bb3d-3ae06dd166c8$t$, $t$9143$t$, $t$ranitidine$t$, $t$(s) relieves heartburn associated with acid indigestion and sour stomach prevents heartburn associated with acid indigestion and sour stomach brought on by eating or drinking certain foods and beverages$t$, $t$Adults and children 12 years and over: to relieve symptoms, swallow 1 tablet with a glass of water to prevent symptoms, swallow 1 tablet with a glass of water 30 to 60 minutes before eating food or drinking beverages that cause heartburn can be used up to twice daily (do not take more than 2 tablets in 24 hours) children under 12 years: ask a doctor$t$, $t$Allergy alert: Do not use if you are allergic to ranitidine or other acid reducers Do not use if you have trouble or pain swallowing food, vomiting with blood, or bloody or black stools.These may be signs of a serious condition. See your doctor. with other acid reducers Ask a doctor before use if you have had heartburn over 3 months. This may be a sign of a more serious condition. heartburn with lightheadedness, sweating or dizziness chest pain or shoulder pain with shortness of breath; sweating; …$t$, $t$Stop use and ask doctor if your heartburn continues or worsens you need to take this product for more than 14 days$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=00df8a42-296f-80dd-98af-ee8b30eb38cc$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$9f51701e-daf4-410b-bd3a-7729d67948ef$t$, $t$1008377$t$, $t$calcium chloride / potassium chloride / sodium chloride / sodium lactate$t$, $t$INDICATIONS AND USAGE: Lactated Ringer's Injection is indicated as a source of water and electrolytes or as an alkalinizing agent.$t$, $t$DOSAGE AND ADMINISTRATION: As directed by a physician. Dosage, rate and duration of administration are to be individualized and dependent upon the indication for use, the patient's age, weight, concomitant treatment and clinical condition of the patient as well as laboratory determinations. All injections in flexible plastic containers are intended for intravenous administration using sterile and nonpyrogenic equipment. …$t$, $t$Although Lactated Ringer's Injection has a potassium concentration similar to the concentration in plasma, it is insufficient to produce a useful effect in case of severe potassium deficiency; therefore, it should not be used for this purpose. Lactated Ringer's Injection is not for use for the treatment of lactic acidosis or severe metabolic acidosis. …$t$, $t$ADVERSE REACTIONS: Post-Marketing Adverse Reactions The following adverse reactions have been reported in the post-marketing experience, listed by MedDRA System Organ Class (SOC). Immune System Disorders Hypersensitivity/infusion reactions, including anaphylactic/anaphylactoid reactions, and the following manifestations: angioedema, chest pain, chest discomfort, decreased heart rate, tachycardia, blood pressure decreased, respiratory distress, bronchospasm, dyspnea, cough, urticaria, rash, pruritus, erythema, …$t$, $t$Drug Interactions Ceftriaxone (see CONTRAINDICATIONS ). Caution is advised when administering Lactated Ringer's Injection to patients treated with drugs that may increase the risk of sodium and fluid retention, such as corticosteroids. Caution is advised when administering Lactated Ringer's Injection to patients treated with drugs for which renal elimination is pH dependent. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=7a723a23-3bc1-4f69-b82f-d06a35dc68d6$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$b3fa6fd6-314c-449a-aeb7-c04db300235b$t$, $t$435$t$, $t$albuterol$t$, $t$Albuterol Sulfate HFA is a beta 2 -adrenergic agonist indicated for: Treatment or prevention of bronchospasm in adult and pediatric patients aged 4 years and older with reversible obstructive airway disease. Prevention of exercise-induced bronchospasm in adult and pediatric patients aged 4 years and older. …$t$, $t$For oral inhalation only. Treatment or prevention of bronchospasm in adult and pediatric patients aged 4 years and older: 2 inhalations by oral inhalation every 4 to 6 hours. For some patients, 1 inhalation every 4 hours may be sufficient. Prevention of exercise-induced bronchospasm in adult and pediatric patients aged 4 years and older: 2 inhalations by oral inhalation 15 to 30 minutes before exercise. …$t$, $t$Life-threatening paradoxical bronchospasm may occur. Discontinue Albuterol Sulfate HFA immediately and institute alternative therapy. Need for more doses of Albuterol Sulfate HFA than usual may be a sign of deterioration of asthma and requires reevaluation of treatment. Albuterol Sulfate HFA is not a substitute for corticosteroids. Cardiovascular effects may occur. Use with caution in patients sensitive to sympathomimetic drugs and patients with cardiovascular or convulsive disorders. Excessive use may be fatal. …$t$, $t$Paradoxical bronchospasm Cardiovascular effects Hypersensitivity reactions, including anaphylaxis Hypokalemia Most common adverse reactions (incidence ≥3%) are throat irritation, viral respiratory infections, upper respiratory inflammation, cough, and musculoskeletal pain. …$t$, $t$Other short-acting sympathomimetic aerosol bronchodilators should not be used concomitantly with albuterol. If additional adrenergic drugs are to be administered by any route, they should be used with caution to avoid deleterious cardiovascular effects. Beta-blockers: Use with caution. May block bronchodilatory effects of beta-agonists and produce severe bronchospasm. Diuretics: Use with caution. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=04c8a345-0a0d-5a01-e063-6294a90a40d2$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$96a0142c-7d9a-4ec4-87b0-abf9dfa51713$t$, $t$435$t$, $t$albuterol$t$, $t$Albuterol tablets, USP are indicated for the relief of bronchospasm in adults and children 6 years of age and older with reversible obstructive airway disease.$t$, $t$The following dosages of albuterol tablets, USP are expressed in terms of albuterol base. Usual Dosage Pediatric Patients 6 to 12 Years of Age: For pediatric patients 6 to 12 years of age, the usual dosage is 2 mg three or four times a day. Adults and Pediatric Patients Over 12 Years of Age: For adults and pediatric patients over 12 years of age, the usual starting dosage is 2 or 4 mg three or four times a day. …$t$, $t$Paradoxical Bronchospasm Albuterol tablets can produce paradoxical bronchospasm, which may be life threatening. If paradoxical bronchospasm occurs, albuterol tablets should be discontinued immediately and alternative therapy instituted. Deterioration of Asthma Asthma may deteriorate acutely over a period of hours, or chronically over several days or longer. …$t$, $t$The adverse reactions to albuterol are similar in nature to those of other sympathomimetic agents. Albuterol Tablets Adverse Experience Incidence (% of patients) in Adults and Children 6 Years of Age and Older Adverse Event Percent Incidence Central nervous system Nervousness 20 Tremor 20 Headache 7 Dizziness 2 Weakness 2 Sleeplessness 2 Irritability < 1 Drowsiness < 1 Restlessness < 1 Cardiovascular Palpitations 5 Tachycardia 5 Flushing < 1 Chest discomfort < 1 Musculoskeletal Muscle cramps 3 Gastrointestinal …$t$, $t$Drug Interactions The concomitant use of albuterol tablets and other oral sympathomimetic agents is not recommended since such combined use may lead to deleterious cardiovascular effects. This recommendation does not preclude the judicious use of an aerosol bronchodilator of the adrenergic stimulant type in patients receiving albuterol tablets. Such concomitant use, however, should be individualized and not given on a routine basis. …$t$, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=230d66fc-f62c-42a6-adb3-0a0f879c8ad4$t$, now())
  on conflict (drug_id) do update set rxcui = excluded.rxcui, matched_name = excluded.matched_name, uses = excluded.uses, how_to_take = excluded.how_to_take, warnings = excluded.warnings, side_effects = excluded.side_effects, interactions = excluded.interactions, source_url = excluded.source_url, fetched_at = now();
insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$4a7910a8-c340-444f-b608-b628b31c4a3f$t$, $t$9793$t$, $t$silver sulfadiazine$t$, $t$Silver sulfadiazine cream, USP 1% is a topical antimicrobial drug indicated as an adjunct for the prevention and treatment of wound sepsis in patients with second and third degree burns.$t$, $t$Prompt institution of appropriate regimens for care of the burned patient is of prime importance and includes the control of shock and pain. The burn wounds are then cleansed and debrided; silver sulfadiazine cream, USP 1% is then applied under sterile conditions. The burn areas should be covered with silver sulfadiazine cream, USP 1% at all times. The cream should be applied once to twice daily to a thickness of approximately one sixteenth of an inch. …$t$, $t$Absorption of silver sulfadiazine varies depending upon the percent of body surface area and the extent of the tissue damage. Although few have been reported, it is possible that any adverse reaction associated with sulfonamides may occur. Some of the reactions which have been associated with sulfonamides are as follows: blood dyscrasias including agranulocytosis, aplastic anemia, thrombocytopenia, leukopenia, and hemolytic anemia; …$t$, $t$Several cases of transient leukopenia have been reported in patients receiving silver sulfadiazine therapy. 1,2,3 Leukopenia associated with silver sulfadiazine administration is primarily characterized by decreased neutrophil count. Maximal white blood cell depression occurs within two to four days of initiation of therapy. Rebound to normal leukocyte levels follows onset within two to three days. Recovery is not influenced by continuation of silver sulfadiazine therapy. …$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=067895f9-a797-4cbd-a3d2-d611d512fe5b$t$, now())
