insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$68861a9a-6dc4-40c6-9843-67b1856d15bb$t$, $t$9863$t$, $t$sodium chloride$t$, $t$Moisturizes dry, irritated, or crusty nasal passages due to low humidity, heated environments, air travel, allergies or colds. Helps loosens mucus secretions to aid aspiration and removal from nose and sinuses allowing for easier breathing. For newborns/infant this can be assisted with the use of our specially soft tip nasal Aspirator Warnings Directions (For nasal use only) Newborns/ Infants - 2 to 6 drops in each nostril as often as needed or as directed by your doctor. …$t$, $t$(For nasal use only) Newborns/ Infants - 2 to 6 drops in each nostril as often as needed or as directed by your doctor. Children & Adults -2 to 6 Sprays /drops into each nostril as often as needed or as directed by a doctor. Other Information This product is non-medicated and can be used as often as needed without the worry of any harmful side effects or drug interactions. The specially buffered formula is alcohol free and helps moisturize nasal membranes. …$t$, $t$Directions (For nasal use only) Newborns/ Infants - 2 to 6 drops in each nostril as often as needed or as directed by your doctor. Children & Adults -2 to 6 Sprays /drops into each nostril as often as needed or as directed by a doctor. Other Information This product is non-medicated and can be used as often as needed without the worry of any harmful side effects or drug interactions. The specially buffered formula is alcohol free and helps moisturize nasal membranes. …$t$, null, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=06906744-49a5-4bab-8539-af2d235df9e8$t$, now())
