insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$d2757956-c86f-451d-9e16-03549f44b246$t$, $t$1151$t$, $t$ascorbic acid$t$, $t$Supplementation of the diet with vitamins A, C and D. Tri-Vite Drops with Fluoride 0.25 mg also provides fluoride for caries prophylaxis. The American Academy of Pediatrics recommends that children up to age 16, in areas where drinking water contains less than optimal levels of fluoride, receive daily fluoride supplementation. …$t$, $t$DOSAGE AND ADMINISTRATION 1.0 mL daily or as directed by physician. May be dropped directly into the mouth with dropper; or mixed with cereal, fruit juice or other food. Tri-Vite Drops with Fluoride 0.25 mg is available in 50 mL bottles with accompanying calibrated dropper.$t$, $t$As in the case of all medications, keep out of reach of children.$t$, $t$Allergic rash and other idiosyncrasies have been rarely reported.$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=003181d4-5412-4ffe-b99d-880f2010e3ad$t$, now())
