insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$26daaf17-0b72-443f-997e-b3cd66133e6e$t$, $t$39841$t$, $t$xylometazoline$t$, $t$Adults and children 7 years and older: Spray into the nose 3 times a day$t$, $t$For nasal use$t$, $t$■ When using this product Stop use and ask a doctor if nervousness, diziness, or sleepness occur. Pain, nasal congestion or cough gets worse or lasts more than 7 days. fever gets worse or lasts more than 3 days New symtoms occur. keep out of reach of children. In case of overdose, get medical help or contact a poison contral center right away. If pregnant or breast-feeding, ask a health professional before use.$t$, null, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=e9da6f39-8620-faca-e053-2995a90a8a57$t$, now())
