insert into public.drug_info (drug_id, rxcui, matched_name, uses, how_to_take, warnings, side_effects, interactions, source_url, fetched_at) values ($t$ca4dabff-ed2f-44bd-b1fd-44ddeafd2f4e$t$, $t$39954$t$, $t$zinc sulfate$t$, $t$See symptoms on front panel. Relieves muscle cramps in legs and arms *$t$, $t$Adults and children: At the onset of symptoms, dissolve 5 pellets under the tongue 3 times a day until symptoms are relieved or as directed by a doctor.$t$, null, $t$Stop use and ask a doctor if symptoms persist for more than 3 days or worsen.$t$, null, $t$https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=21b581c7-06e8-dea3-e063-6294a90a91a3$t$, now())
